#!/usr/bin/env bash
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)"
cd "$repo_root"

# This first checks that the raw claim roster is generated by the accepted
# verifier-owned mask and native point projection, before it enters the
# coefficient planner below.
bash formal/s31/tests/run_pcs_fri_p05_projected_map_native.sh

zig test -O ReleaseSafe -j2 \
  --test-filter 'P05 accepted sparse OOD plans bind projected points to all factor slots' \
  --dep stwo_core --dep stwo_prover \
  -Mroot=formal/s31/tests/pcs_fri_p05_sparse_ood_factors_native.zig \
  -Mstwo_core=deps/stwo-zig/src/core/mod.zig \
  --dep stwo_core --dep stwo_prover_api -Mstwo_prover=deps/stwo-zig/src/prover/mod.zig \
  -Mstwo_prover_api=deps/stwo-zig/src/prover_api/mod.zig
